package com.java.operators.loops;

public class oddeven_loops {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
       int x =2;
       for(int i=x;i<=20;i++) {
    	   if(i%2==0) {
    		   System.out.println("even :"+i);
    	   }
    	   else {
    		   System.out.println("odd : "+i);
    	   }
       }
	}

}
